_CORE_SRC = '# Action: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: 3.0 per truck and 1.5 per scooter not on its own player\'s base.\n# Moves precede service; stock regenerates after service, rounded to 2 decimals.\n\nimport time\nimport heapq\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nCAPACITY = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\ndef payout(own, enemy, stock):\n    denominator = max(own + enemy, stock)\n    return own * stock / denominator if denominator > 0 else 0.0\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.dist = None\n        self.reach = None\n        self.previous_enemy = {}\n        self.mobility = 0.65\n        self.previous_plan = {}\n        self.previous_turn = -2\n        self.bad_reports = 0\n\n    def preprocess_map(self, obs):\n        n = int(obs["n_nodes"])\n        adjacency = [[] for _ in range(n)]\n        for a, b in obs["edges"]:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n        distances = []\n        for source in range(n):\n            d = [n + 1] * n\n            d[source] = 0\n            queue = deque([source])\n            while queue:\n                u = queue.popleft()\n                for v in sorted(adjacency[u]):\n                    if d[v] > d[u] + 1:\n                        d[v] = d[u] + 1\n                        queue.append(v)\n            distances.append(d)\n        self.dist = distances\n        self.reach = {\n            speed: [\n                [v for v in range(n) if distances[u][v] <= speed]\n                for u in range(n)\n            ]\n            for speed in (1, 2)\n        }\n\n    def step_toward(self, source, target, speed):\n        return min(self.reach[speed][source],\n                   key=lambda v: (self.dist[v][target], v))\n\n    def predict_opponent(self, obs, horizon):\n        """Blend legal greedy movement and staying at the last visible position."""\n        n = int(obs["n_nodes"])\n        enemies = obs["opponent_units"]\n        if self.previous_enemy and int(obs["turn"]) == self.previous_turn + 1:\n            changed = sum(\n                int(position != self.previous_enemy.get(uid, position))\n                for uid, (_, position) in enemies.items()\n            )\n            observed = changed / max(1, len(enemies))\n            self.mobility = 0.65 * self.mobility + 0.35 * observed\n\n        positions = {uid: int(data[1]) for uid, data in enemies.items()}\n        stock = list(obs["stock"])\n        maximum = obs["stock_max"]\n        regen = obs["regen"]\n        base = int(obs["opponent_base"])\n        prediction = []\n        # Even a stationary opponent can start moving later; retain a small hedge.\n        blend = max(0.06, min(0.9, self.mobility))\n        for t in range(horizon):\n            allocation = [0.0] * n\n            for uid in sorted(enemies, key=lambda u: (-CAPACITY[enemies[u][0]], u)):\n                kind = enemies[uid][0]\n                cap, cost, speed = CAPACITY[kind], COST[kind], SPEED[kind]\n                source = positions[uid]\n                best_value, best_node = -1e30, source\n                for v in self.reach[speed][source]:\n                    gain = (min(stock[v], allocation[v] + cap)\n                            - min(stock[v], allocation[v]))\n                    value = gain - (cost if v != base else 0.0)\n                    # Small continuation preference, without assuming an illegal jump.\n                    value += 0.10 * max(0.0, stock[v] - allocation[v] - cap)\n                    if v == source:\n                        value += 0.04\n                    if value > best_value:\n                        best_value, best_node = value, v\n                positions[uid] = best_node\n                allocation[best_node] += cap\n            capacities = [blend * c for c in allocation]\n            for uid, (kind, original) in enemies.items():\n                capacities[original] += (1.0 - blend) * CAPACITY[kind]\n            prediction.append(capacities)\n            stock = [\n                round(min(maximum[v], max(0.0, stock[v] - capacities[v])\n                          + regen[v]), 2)\n                for v in range(n)\n            ]\n        return prediction\n\n    def plan(self, obs, deadline):\n        n = int(obs["n_nodes"])\n        base = int(obs["player_base"])\n        units = obs["player_units"]\n        horizon = min(7, N_TURNS - int(obs["turn"]))\n        enemy = self.predict_opponent(obs, horizon)\n        discount = [0.93 ** t for t in range(horizon)]\n        maximum, regen = obs["stock_max"], obs["regen"]\n        initial_stock = obs["stock"]\n        plans = {}\n\n        for uid, (kind, source) in units.items():\n            speed = SPEED[kind]\n            old = self.previous_plan.get(uid, [])\n            route = old[1:] if self.previous_turn + 1 == obs["turn"] else []\n            position = source\n            new = []\n            for t in range(horizon):\n                target = route[t] if t < len(route) else base\n                position = self.step_toward(position, target, speed)\n                new.append(position)\n            plans[uid] = new\n\n        def capacities(exclude=None):\n            result = [[0.0] * n for _ in range(horizon)]\n            for uid, route in plans.items():\n                if uid != exclude:\n                    cap = CAPACITY[units[uid][0]]\n                    for t, v in enumerate(route):\n                        result[t][v] += cap\n            return result\n\n        def evaluate(background, route=None, kind=None, trace=False):\n            stock = list(initial_stock)\n            value = 0.0\n            stocks = []\n            cap = CAPACITY[kind] if kind else 0\n            for t in range(horizon):\n                if trace:\n                    stocks.append(list(stock))\n                for v in range(n):\n                    own = background[t][v]\n                    if route is not None and route[t] == v:\n                        own += cap\n                    other = enemy[t][v]\n                    value += discount[t] * (\n                        payout(own, other, stock[v]) -\n                        payout(other, own, stock[v])\n                    )\n                    stock[v] = round(min(\n                        maximum[v], max(0.0, stock[v] - own - other) + regen[v]\n                    ), 2)\n                if route is not None and route[t] != base:\n                    value -= discount[t] * COST[kind]\n            if route is not None:\n                # Approximate the obligation to pay while returning after the horizon.\n                if int(obs["turn"]) + horizon < N_TURNS:\n                    return_steps = (self.dist[route[-1]][base] + SPEED[kind] - 1) // SPEED[kind]\n                    value -= discount[-1] * COST[kind] * return_steps * 0.65\n            return (value, stocks) if trace else value\n\n        # Larger vehicles get first access to early stock; later passes can retire them.\n        order = []\n        for uid, (kind, source) in units.items():\n            heapq.heappush(order, (-CAPACITY[kind], uid))\n        ordered = [heapq.heappop(order)[1] for _ in range(len(order))]\n\n        for sweep in range(3):\n            for uid in ordered:\n                if time.perf_counter() >= deadline:\n                    return plans\n                kind, source = units[uid]\n                cap, cost, speed = CAPACITY[kind], COST[kind], SPEED[kind]\n                background = capacities(uid)\n                _, stocks = evaluate(background, trace=True)\n                candidates = [plans[uid]]\n\n                # Marginal-margin dynamic program: legal movement, denial, and cost.\n                values = {source: (0.0, [])}\n                for t in range(horizon):\n                    next_values = {}\n                    for position in sorted(values):\n                        prior, route = values[position]\n                        for v in self.reach[speed][position]:\n                            own, other, stock = background[t][v], enemy[t][v], stocks[t][v]\n                            before = payout(own, other, stock) - payout(other, own, stock)\n                            after = payout(own + cap, other, stock) - payout(other, own + cap, stock)\n                            reward = after - before - (cost if v != base else 0.0)\n                            score = prior + discount[t] * reward\n                            if v not in next_values or score > next_values[v][0]:\n                                next_values[v] = (score, route + [v])\n                    values = next_values\n                ranked = sorted(values.items(), key=lambda item: (\n                    -(item[1][0] - 0.5 * cost * self.dist[item[0]][base] / speed),\n                    item[0]))\n                candidates.extend(data[1] for _, data in ranked[:3])\n\n                # Constant destinations provide stable alternatives to the optimistic DP.\n                for target in range(n):\n                    position = source\n                    route = []\n                    for _ in range(horizon):\n                        position = self.step_toward(position, target, speed)\n                        route.append(position)\n                    candidates.append(route)\n\n                best = plans[uid]\n                best_value = evaluate(background, best, kind)\n                for route in candidates[1:]:\n                    if time.perf_counter() >= deadline:\n                        break\n                    value = evaluate(background, route, kind)\n                    if value > best_value + 0.04:\n                        best_value, best = value, route\n                plans[uid] = best\n        return plans\n\n    def legal_action(self, obs, plans):\n        moves = {}\n        n = int(obs["n_nodes"])\n        for uid, (kind, source) in obs["player_units"].items():\n            route = plans.get(uid, [])\n            if not route:\n                continue\n            destination = int(route[0])\n            if (0 <= destination < n\n                    and self.dist[source][destination] <= SPEED[kind]\n                    and destination != source):\n                moves[str(uid)] = int(destination)\n        return {"moves": moves}\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.57 * TIME_BUDGET)\n        if self.dist is None:\n            self.preprocess_map(obs)\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n\n        if self.bad_reports >= 2:\n            # Conservative, independently checked recall after repeated feedback errors.\n            base = int(obs["player_base"])\n            plans = {\n                uid: [self.step_toward(source, base, SPEED[kind])]\n                for uid, (kind, source) in obs["player_units"].items()\n            }\n        else:\n            plans = self.plan(obs, deadline)\n\n        action = self.legal_action(obs, plans)\n        self.previous_plan = plans\n        self.previous_enemy = {\n            uid: int(data[1]) for uid, data in obs["opponent_units"].items()\n        }\n        self.previous_turn = int(obs["turn"])\n        return action\n'
