_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Running cost: 3.0 per deployed truck and 1.5 per deployed scooter per turn;\n# couriers on their own base cost nothing. Moves happen before service and costs.\n#\n# Conservative, observation-only planning: never travel speculatively. Every\n# harvesting step must pay its cost AND any increase in the reserved cost of\n# returning home. Unprofitable couriers return by a shortest route. Against an\n# idle opponent, this maintains nonnegative profit, including eventual returns.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nCAPACITY = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [n + 1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if row[neighbor] == n + 1:\n                    row[neighbor] = row[node] + 1\n                    queue.append(neighbor)\n        distances.append(row)\n\n    reachable = {\n        speed: [\n            [v for v in range(n) if distances[u][v] <= speed]\n            for u in range(n)\n        ]\n        for speed in (1, 2)\n    }\n    return distances, reachable\n\n\ndef payout(own_capacity, opponent_capacity, stock):\n    denominator = max(own_capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * stock / denominator\n\n\ndef return_reserve(node, home, speed, cost, distances):\n    # The final move onto home is free; earlier return moves cost money.\n    steps = (distances[node][home] + speed - 1) // speed\n    return max(steps - 1, 0) * cost\n\n\ndef make_plan(obs, distances, reachable):\n    n = int(obs["n_nodes"])\n    home = int(obs["player_base"])\n    units = obs.get("player_units", {})\n    stock = obs.get("stock", [0.0] * n)\n    turns_left = max(0, N_TURNS - int(obs.get("turn", 0)))\n    if turns_left == 0:\n        return {}\n\n    opponent_capacity = [0] * n\n    for kind, node in obs.get("opponent_units", {}).values():\n        if kind in CAPACITY and 0 <= node < n:\n            opponent_capacity[node] += CAPACITY[kind]\n\n    assigned_capacity = [0] * n\n    plan = {}\n\n    # Trucks harvest efficiently; deployed units get first choice so that\n    # launching a new unit cannot displace their opportunity to earn.\n    ordered_ids = sorted(\n        units,\n        key=lambda uid: (\n            units[uid][1] == home,\n            units[uid][0] != "truck",\n            uid,\n        ),\n    )\n\n    for uid in ordered_ids:\n        kind, source = units[uid]\n        if kind not in SPEED or not 0 <= source < n:\n            continue\n        speed, cost, capacity = SPEED[kind], COST[kind], CAPACITY[kind]\n        candidates = reachable[speed][source]\n        old_reserve = return_reserve(source, home, speed, cost, distances)\n\n        def marginal_revenue(destination):\n            if destination == home:\n                return 0.0\n            existing = assigned_capacity[destination]\n            opposing = opponent_capacity[destination]\n            return (\n                payout(existing + capacity, opposing, stock[destination])\n                - payout(existing, opposing, stock[destination])\n            )\n\n        def safe_value(destination):\n            running_cost = 0.0 if destination == home else cost\n            reserve = return_reserve(\n                destination, home, speed, cost, distances\n            )\n            return (\n                marginal_revenue(destination)\n                - running_cost\n                + old_reserve\n                - reserve\n            )\n\n        # Always have a legal, fully budgeted return move available.\n        return_distance = min(distances[v][home] for v in candidates)\n        returning = [\n            v for v in candidates if distances[v][home] == return_distance\n        ]\n        destination = max(\n            returning,\n            key=lambda v: (safe_value(v), -v),\n        )\n        best_value = safe_value(destination)\n\n        for target in candidates:\n            if target == home or opponent_capacity[target] > 0:\n                continue  # Do not initiate marginal contests.\n            # Leave sufficient time for a normal return; this is deliberately\n            # more conservative than necessary on the last turns.\n            return_steps = (distances[target][home] + speed - 1) // speed\n            if return_steps >= turns_left:\n                continue\n\n            value = safe_value(target)\n            # A clear surplus, rather than break-even wandering.\n            if value >= 0.5 and value > best_value + 0.25:\n                destination = target\n                best_value = value\n\n        plan[uid] = destination\n        if destination != home:\n            assigned_capacity[destination] += capacity\n\n    return plan\n\n\ndef legal_action(plan, units, n, distances):\n    moves = {}\n    for uid in sorted(plan):\n        if uid not in units or not isinstance(uid, str):\n            continue\n        kind, source = units[uid]\n        if kind not in SPEED or not 0 <= source < n:\n            continue\n        destination = int(plan[uid])\n        if (\n            0 <= destination < n\n            and distances[source][destination] <= SPEED[kind]\n            and destination != source\n        ):\n            moves[uid] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_key = None\n        self._distances = None\n        self._reachable = None\n\n    def act(self, obs):\n        # Work is bounded: at most 13 BFS roots and 12 * 13 candidates.\n        # No search, randomness, or dynamic strategy state is needed.\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(a), int(b)) for a, b in edges))\n        if key != self._map_key:\n            distances, reachable = preprocess_map(n, edges)\n            self._distances = distances\n            self._reachable = reachable\n            self._map_key = key\n\n        plan = make_plan(obs, self._distances, self._reachable)\n        return legal_action(\n            plan, obs.get("player_units", {}), n, self._distances\n        )\n'
